(()=>{"use strict";window.NAILS.ADMIN.registerPlugin("nails/module-email","UserTabSubscriptions",(function(s){return new class{constructor(s){this.adminController=s,console.log(s),this.init()}init(){$(".js-email-subscriptions").find(".js-subscribe-action").on("click",(s=>{s.preventDefault(),s.stopPropagation();let e=$(s.currentTarget),t=e.closest(".js-row"),i=t.data("type"),r=t.closest(".js-email-subscriptions").data("user-id");switch(e.data("action")){case"subscribe":this.subscribe(r,i,t);break;case"unsubscribe":this.unsubscribe(r,i,t)}}))}subscribe(s,e,t){this.api(s,e,"subscribe")&&this.setLabel(t,"Subscribed").setStatus(t,"success").setHint(t,"User will receive this type of email").showUnsubscribeButton(t)}unsubscribe(s,e,t){this.api(s,e,"unsubscribe")&&this.setLabel(t,"Unsubscribed").setStatus(t,"danger").setHint(t,"User will not received this type of email").showSubscribeButton(t)}async api(s,e,t){try{let i;if("subscribe"===t)i=`${window.SITE_URL}/api/email/admin/subscribe`;else{if("unsubscribe"!==t)throw new Error("Invalid action; must be subscribe or unsubscribe");i=`${window.SITE_URL}/api/email/admin/unsubscribe`}const r={userId:s,type:e},n=await fetch(i,{method:"PUT",headers:{"Content-Type":"application/json;charset=UTF-8"},body:JSON.stringify(r)});if(!n.ok)throw new Error("Network response was not ok "+n.statusText);await n.json(),this.adminController.log(`Successfully set ${s} as ${t} from ${e}`)}catch(s){return this.adminController.error("Error:",s),!1}return!0}setLabel(s,e){return s.find(".js-label").text(e),this}setStatus(s,e){return s.find(".js-status").removeClass("success danger").addClass(e),this}setHint(s,e){return s.find(".js-label").attr("aria-label",e),this}showSubscribeButton(s){return s.find(".js-subscribe-action").text("Subscribe").data("action","subscribe").removeClass("btn-danger").addClass("btn-success"),this}showUnsubscribeButton(s){return s.find(".js-subscribe-action").text("Unsubscribe").data("action","unsubscribe").removeClass("btn-success").addClass("btn-danger"),this}}(s)}))})();